int check_ptr_alignment(struct bpf_verifier_env *env, const struct bpf_reg_state *reg, int off, int size) {
    int align = 0;
    int base_off = reg->off;

    if (off < 0) {
        /* Cannot check alignment for negative offsets */
        return -EINVAL;
    }

    switch (reg->type) {
    case PTR_TO_PACKET:
        align = 1;
        break;
    case PTR_TO_CTX:
        align = __alignof__(struct bpf_context);
        break;
    case PTR_TO_STACK:
        align = __alignof__(long);
        break;
    default:
        align = 1;
        break;
    }

    if ((base_off + off) % align != 0) {
        return -EINVAL;
    }

    return 0;
}

int check_pointer_alignment(struct bpf_verifier_env *env, const struct bpf_reg_state *reg, int off, int size) {
    int ptr_type = reg->type;
    int align = 1;

    switch (ptr_type) {
        case PTR_TO_PACKET:
        case PTR_TO_PACKET_META:
            align = 1;
            break;
        case PTR_TO_CTX:
            align = __alignof__(union bpf_attr);
            break;
        case PTR_TO_MAP_KEY:
        case PTR_TO_MAP_VALUE:
            align = reg->id ? reg->real_id : reg->off;
            break;
        default:
            if (reg->smin_value == reg->smax_value)
                align = reg->smin_value;
            else if (reg->smin_value > 0)
                align = reg->smin_value;
            else
                align = 1;
            break;
    }

    if ((off % align) != 0)
        return -EINVAL;

    return 0;
}

int check_alignment(struct bpf_verifier_env *env, const struct bpf_reg_state *reg, int off, int size) {
    // Default to aligned for general pointer types
    if (reg->type == PTR_TO_PACKET) {
        // Adjust alignment logic for packet pointers
        if ((off % size) != 0) {
            return -EINVAL;
        }
    } else if (reg->type == PTR_TO_CTX) {
        // Adjust alignment logic for context pointers
        if (off < 0 || off + size > sizeof(struct bpf_context)) {
            return -EINVAL;
        }
    } else {
        // Default case for other pointer types
        if ((off % size) != 0) {
            return -EINVAL;
        }
    }

    return 0;
}

int check_pointer_alignment(struct bpf_verifier_env *env, const struct bpf_reg_state *reg, int off, int size) {
    int ptr_type = reg->type;

    switch (ptr_type) {
        case PTR_TO_PACKET:
            return check_packet_alignment(env, reg, off, size);
        case PTR_TO_CTX:
            return check_context_alignment(env, reg, off, size);
        case PTR_TO_STACK:
        case PTR_TO_MAP_VALUE:
            return check_stack_or_map_value_alignment(env, reg, off, size);
        default:
            mark_verifier_env(env, VEC_UNKNOWN_PTR_TYPE);
            return -EINVAL;
    }
}

int check_pointer_alignment(struct bpf_verifier_env *env, const struct bpf_reg_state *reg, int off, int size) {
    int align = 0;

    switch (reg->type) {
        case PTR_TO_PACKET:
        case PTR_TO_PACKET_META:
            align = check_packet_pointer_alignment(env, reg, off, size);
            break;
        case PTR_TO_CTX:
            align = check_ctx_pointer_alignment(env, reg, off, size);
            break;
        case PTR_TO_STACK:
        case PTR_TO_BTF_ID:
        case PTR_TO_MAP_KEY:
        case PTR_TO_MAP_VALUE:
            align = check_general_pointer_alignment(env, reg, off, size);
            break;
        default:
            align = 0;
            break;
    }

    if (align != 0) {
        return align;
    }

    return 0;
}
